    }
    if (selectedLayer.kind !== 'pixel') {
      setFilterError('Select a pixel layer to apply a filter.');
      setPreviewDocument(null);
      return;
    }
    try {
      const worldTransform =
        findLayerWorldTransform(document, selectedLayer.id) ?? selectedLayer.transform;
