  const redo = useCallback(() => {
    if (!historyRef.current?.canRedo) return;
    setDocument(historyRef.current.redo());
    setRevision((value) => value + 1);
  }, []);

  const activateCrop = useCallback(() => {
    setTool('crop');
    setChannelView('composite');
    if (document) {
      setCropRectangle({
        x: 0,
        y: 0,
        width: document.canvas.width,
