    if (!next) return;
    closeSizeDialog();
    window.requestAnimationFrame(() => fitTarget(next));
    notify(
      `Canvas resized to ${String(parsedCanvasSize.width)} × ${String(parsedCanvasSize.height)} pixels.`,
    );
  }, [
    canvasSizeDraft.anchor,
    closeSizeDialog,
    document,
    fitTarget,
    notify,
    parsedCanvasSize,
    runCommand,
  ]);


