  const openContextualFilterOperation = useCallback(
    (kind: FilterKind, mode: 'destructive' | 'smart', trigger?: HTMLButtonElement) => {
      if (
        !document ||
        (mode === 'destructive' && selectedLayer?.kind !== 'pixel') ||
        (mode === 'smart' && selectedLayer?.kind !== 'smart-object')
