              min="1"
              max="100"
              value={props.brushOpacity}
              onChange={(event) => props.onBrushOpacityChange(Number(event.target.value))}
            />
            <span>{props.brushOpacity}%</span>
          </div>
          {props.tool === 'brush' && props.editTarget === 'pixels' && (
            <label className="color-option">
              Color
