          contrast: 20,
        },
      };
      runCommand(
        setSmartObjectFilters(selectedLayer.id, [...selectedLayer.smartFilters, defaults[type]]),
      );
      notify(`${type.split('-').join(' ')} smart filter added.`);
    },
    [notify, runCommand, selectedLayer],
