        context.lineDashOffset = 4 / viewport.zoom;
        context.strokeStyle = '#101716';
        context.stroke();
        context.restore();
      }
      if (showSelection && lassoPreview.length > 0) {
        context.save();
        context.setTransform(
          viewport.zoom * ratio,
          0,
          0,
          viewport.zoom * ratio,
          viewport.panX * ratio,
          viewport.panY * ratio,
        );
