          viewport.zoom * ratio,
          0,
          0,
          viewport.zoom * ratio,
          viewport.panX * ratio,
          viewport.panY * ratio,
        );
        context.beginPath();
        context.rect(0, 0, renderedDocument.canvas.width, renderedDocument.canvas.height);
