                const local = transformPoint(
                  invertLayerTransform(transformOverlay.snapshot.worldTransform),
                  point.x,
                  point.y,
                );
                if (
                  local.x >= 0 &&
                  local.y >= 0 &&
                  local.x <= transformOverlay.dimensions.width &&
                  local.y <= transformOverlay.dimensions.height
