          className="size-form"
          onSubmit={(event) => {
            event.preventDefault();
            applyCanvasSize();
          }}
        >
          <p className="dialog-summary">
            Current size: {document?.canvas.width ?? 0} × {document?.canvas.height ?? 0} pixels
