            )}
            <span>
              {document && selectionBounds(document)
                ? (() => {
                    const bounds = selectionBounds(document);
                    return bounds
                      ? `Selection: ${String(bounds.x)}, ${String(bounds.y)} · ${String(bounds.width)} × ${String(bounds.height)}`
                      : 'No selection';
                  })()
                : 'No selection'}
