          </>
        }
      />

      <ModalDialog open={sizeDialog === 'canvas'} title="Canvas Size" onCancel={closeSizeDialog}>
        <form
          className="size-form"
          onSubmit={(event) => {
            event.preventDefault();
            applyCanvasSize();
          }}
