    canvas.width = 32;
    canvas.height = 32;
    const context = canvas.getContext('2d');
    if (!context) throw new Error('Canvas unavailable');
    const pixels = new Uint8ClampedArray(32 * 32 * 4);
    for (let offset = 0; offset < pixels.length; offset += 4) {
      pixels.set(rgba, offset);
